import csv
ids = {
 'air':'e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8',
 'heat':'b7f22e0c-833d-5373-87e1-51e1cb26f038',
 'cool':'5b98cbc1-fd25-5d8c-a96e-c3de49819174',
}
data = {k:[] for k in ids}
with open(VALUES_CSV) as f:
    r = csv.DictReader(f)
    for row in r:
        for k,sid in ids.items():
            if row['timeseries_id']==sid and row['timestamp'].startswith('2018-01-06'):
                data[k].append((row['timestamp'], float(row['value'])))
for k in ids:
    data[k].sort()
print({k:len(v) for k,v in data.items()})
air = {t:v for t,v in data['air']}
heat = {t:v for t,v in data['heat']}
cool = {t:v for t,v in data['cool']}
count = 0
out=[]
for t in air:
    a=air[t]; h=heat.get(t); c=cool.get(t)
    below = a < h if h is not None else None
    above = a > c if c is not None else None
    outside = (below is True) or (above is True)
    if outside: count+=1
    out.append((t,a,h,c,outside))
for o in out: print(o)
print("COUNT OUTSIDE:", count)
